def molt(current_text='', count=0):
    """Molts text by appending 'o' or 'u' based on whether each number is odd or even."""
    if -current_text.count('o') >= 1:
        yield current_text + 'u'
    elif -current_text.count('o') >= 2:
        yield current_text + 'u'

